parameters.jsCode:
/**
 * Normalize 2B orchestrator input (JSON-only)
 * Note: Idempotency is handled by router's "Mark as Processing" step
 * which sets execution_status='processing' before calling this webhook
 */
const input = $json || {};
const body = input.body && input.body !== input ? input.body : input;

const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

const orderId = pick(input.orderId, input.amazonOrderId, body.orderId, body.amazonOrderId, null);
if (!orderId) throw new Error('2B main: orderId is required');

// 2A manifest URL
let manifestUrl = pick(input.manifestUrl, input.originalManifestUrl, body.manifestUrl, body.originalManifestUrl, null);
if (!manifestUrl) {
  const base = pick(input.backendUrl, body.backendUrl, 'https://admin.littleherolabs.com');
  manifestUrl = `${base}/api/manifests/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`;
}

const backendUrl = pick(input.backendUrl, body.backendUrl, 'https://admin.littleherolabs.com');
const callbackUrl = pick(input.callbackUrl, body.callbackUrl, `${backendUrl}/webhook/2b-callback`);

// n8n Cloud-friendly: pass sw1 workflow id in the request payload (or set it directly in the Execute Workflow node UI)
const sw1WorkflowId = pick(input.sw1WorkflowId, body.sw1WorkflowId, null);

const batchSize = 1; // Always 1 so merge+upload runs sequentially per pose (avoids overwriting manifest)
const force = !!pick(input.force, body.force, false);

return [{ json: { orderId, backendUrl, manifestUrl, callbackUrl, sw1WorkflowId, batchSize, force } }];

/**
 * Build pose worklist (idempotent + replacement-aware)
 * Async mode: we only trigger s2B-sw1 and return.
 */
// PSEUDOCODE
// - Always read 2A from the dedicated download node (optional 2B download can overwrite $json)
// - Optionally read existing 2B (404 is OK) to skip already-completed poses
const manifest2a = $items('Download 2A Manifest', 0, $runIndex)?.[0]?.json || {};
if (!manifest2a.schema) throw new Error('2B main: expected manifest JSON from Download 2A Manifest');

// Recover context from Normalize node (HTTP nodes overwrite input)
let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

const orderId = ctx.orderId || manifest2a.order?.amazonOrderId || manifest2a.order?.orderId;
const characterHash = manifest2a.characterHash || manifest2a.order?.characterHash || null;
if (!orderId) throw new Error('2B main: orderId missing after manifest download');
if (!characterHash) throw new Error('2B main: characterHash missing');

const approved = (manifest2a.entries || []).filter(e => e?.approved && e?.status === 'approved');
if (!approved.length) return [{ json: { orderId, characterHash, scheduled: 0, reason: 'NO_APPROVED_POSES' } }];

// Existing 2B manifest (optional) from the previous node
let existing2b = null;
try {
  const maybe = $items('Download 2B Manifest (optional)', 0, $runIndex)?.[0]?.json;
  if (maybe && maybe.schema === 'lhb.run-manifest@v2.0') existing2b = maybe;
} catch {}

const existingEntries = Array.isArray(existing2b?.entries) ? existing2b.entries : [];
const existingByPose = new Map(existingEntries.map(e => [Number(e.poseNumber), e]));

// NOTE: existing 2B manifest lookup occurs in callback for MVP to keep orchestrator lean
// Idempotency can still be applied in callback using sourceApprovedKey/sourceReplacedAt.

const backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
const callbackUrl = ctx.callbackUrl;
const force = !!ctx.force;

let skippedCount = 0;
let skippedByBriaStatus = 0;
let skippedBy2BManifest = 0;

const work = approved
  .filter(p => {
    if (force) return true;
    const poseNum = Number(p?.poseNumber);

    // Existing 2B manifest check (keep as-is)
    const ex = existingByPose.get(poseNum);
    if (!ex) return true;
    const srcKey = p.approvedKey || null;
    const srcReplacedAt = p.replacedAt || null;
    const srcReplacementCount = Number(p.replacementCount || 0);
    const done = !!(
      ex.bgRemovedKey &&
      String(ex.briaStatus || '').toLowerCase() === 'completed' &&
      (ex.sourceApprovedKey || null) === srcKey &&
      ((ex.sourceReplacedAt || null) === srcReplacedAt || Number(ex.sourceReplacementCount || 0) === srcReplacementCount)
    );
    if (done) {
      skippedBy2BManifest++;
      skippedCount++;
    }
    return !done;
  })
  .map(p => ({
  orderId,
  characterHash,
  poseNumber: p.poseNumber,
  approvedKey: p.approvedKey,
  replacedAt: p.replacedAt || null,
  replacementCount: Number(p.replacementCount || 0),
  manifest2aUrl: ctx.manifestUrl || null,
  backendUrl,
  callbackUrl,
  force
}));

// If all poses were skipped, emit a summary item instead of empty array
if (work.length === 0 && approved.length > 0) {
  return [{ json: { 
    orderId, 
    characterHash, 
    scheduled: 0, 
    reason: 'ALL_POSES_ALREADY_PROCESSED',
    totalApproved: approved.length,
    skippedByBriaStatus,
    skippedBy2BManifest,
    skippedTotal: skippedCount
  } }];
}

// Emit one item per pose for SplitInBatches
return work.map(w => ({ json: w }));

/**
 * Final response payload (does not wait for workers).
 */
const items = $items('Build Worklist', 0, $runIndex) || [];
let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}
return [{ json: { orderId: ctx.orderId, scheduled: items.length, callbackUrl: ctx.callbackUrl, batchSize: ctx.batchSize } }];

/**
 * Normalize Result - Extract and normalize sub-workflow output for aggregator
 * Handles both flat result structure and any wrapper formats
 */
const j = $json || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

// Extract result (may be flat or wrapped)
let result = j.result || j;

// Recover context from orchestrator
let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

// Extract fields with fallbacks
const orderId = pick(result.orderId, j.orderId, ctx.orderId, null);
const characterHash = pick(result.characterHash, j.characterHash, ctx.characterHash, null);
const poseNumberRaw = pick(result.poseNumber, j.poseNumber, null);
const poseNumber = (poseNumberRaw === 0 || poseNumberRaw === '0') ? 0 : Number(poseNumberRaw);

if (!orderId) throw new Error('2B aggregator: orderId required');
if (!characterHash) throw new Error('2B aggregator: characterHash required');
if (!Number.isFinite(poseNumber)) throw new Error('2B aggregator: poseNumber required');

const backendUrl = pick(result.backendUrl, j.backendUrl, ctx.backendUrl, 'https://admin.littleherolabs.com');
const manifest2aUrl = pick(result.manifest2aUrl, j.manifest2aUrl, ctx.manifestUrl, `${backendUrl}/api/manifests/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`);
const manifest2bKey = `book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2b-manifest.json`;

// Normalize result object
const normalizedResult = {
  orderId,
  characterHash,
  poseNumber,
  approvedKey: pick(result.approvedKey, null),
  sourceReplacedAt: pick(result.sourceReplacedAt, null),
  sourceReplacementCount: Number(pick(result.sourceReplacementCount, 0) || 0),
  sourceUrl: pick(result.sourceUrl, null),
  briaStatus: pick(result.briaStatus, 'error'),
  briaRequestId: pick(result.briaRequestId, null),
  briaStatusUrl: pick(result.briaStatusUrl, null),
  briaCompletedAt: pick(result.briaCompletedAt, null),
  briaErrorMessage: pick(result.briaErrorMessage, null),
  bgRemovedKey: pick(result.bgRemovedKey, null),
  bgRemovedContentType: pick(result.bgRemovedContentType, null),
  bgRemovedSizeBytes: (result.bgRemovedSizeBytes === 0 ? 0 : (Number(result.bgRemovedSizeBytes) || null)),
  bgRemovedImageUrl: pick(result.bgRemovedImageUrl, null),
  qa: (result.qa && typeof result.qa === 'object') ? result.qa : null,
  needsReview: !!pick(result.needsReview, false),
  reviewReason: pick(result.reviewReason, null),
};

return [{ json: { backendUrl, manifest2aUrl, manifest2bKey, result: normalizedResult } }];

/**
 * Merge the incoming pose result into 2B manifest (create if missing).
 * Uses $items() to access parallel download nodes reliably
 */
let ctx = {};
try { ctx = $items('Normalize Result', 0, $runIndex)?.[0]?.json || {}; } catch {}
const incoming = ctx.result;

const manifest2bMaybe = $items('Download 2B Manifest (if exists)', 0, $runIndex)?.[0]?.json || null;
const manifest2a = $items('Download 2A Manifest (for merge)', 0, $runIndex)?.[0]?.json || null;

if (!incoming) {
  throw new Error('2B aggregator: No result data from Normalize Result');
}

if (!manifest2a?.schema) {
  throw new Error('2B aggregator: missing 2A manifest or invalid schema');
}

// Detect 2B manifest existence: backend returns JSON error on 404; treat as missing if no schema
let manifest2b = (manifest2bMaybe && manifest2bMaybe.schema === 'lhb.run-manifest@v2.0') ? manifest2bMaybe : null;

if (!manifest2b) {
  // Create skeleton 2B manifest from 2A
  manifest2b = JSON.parse(JSON.stringify(manifest2a));
  manifest2b.stage = '2b';
  manifest2b.createdAt = new Date().toISOString();
  manifest2b.updatedAt = new Date().toISOString();
  (manifest2b.entries || []).forEach(e => {
    e.bgRemovedKey = null;
    e.bgRemovedImageUrl = null;
    e.briaStatus = null;
    e.briaRequestId = null;
    e.briaStatusUrl = null;
    e.briaErrorMessage = null;
    e.sourceApprovedKey = null;
    e.sourceReplacedAt = null;
    e.sourceReplacementCount = 0;
    e.processedAt = null;
    // Clear 2B-specific review flags (start fresh for 2B workflow)
    e.needsReview = false;
    e.reviewReason = null;
    e.isFlagged = false;
  });
}

// Update pose entry
const poseNumber = Number(incoming.poseNumber);
const entry = (manifest2b.entries || []).find(e => Number(e.poseNumber) === poseNumber);
if (!entry) throw new Error(`2B aggregator: pose ${poseNumber} not found in manifest entries`);

entry.sourceApprovedKey = incoming.approvedKey || entry.approvedKey || null;
entry.sourceReplacedAt = incoming.sourceReplacedAt || null;
entry.sourceReplacementCount = Number(incoming.sourceReplacementCount || 0);
entry.processedAt = new Date().toISOString();

entry.briaStatus = incoming.briaStatus;
entry.briaRequestId = incoming.briaRequestId || null;
entry.briaStatusUrl = incoming.briaStatusUrl || null;
entry.briaErrorMessage = incoming.briaErrorMessage || null;

// QA
if (incoming.qa && typeof incoming.qa === 'object') {
  entry.qa = { ...(entry.qa || {}), ...incoming.qa };
}

if (incoming.briaStatus === 'completed') {
  entry.bgRemovedKey = incoming.bgRemovedKey || entry.bgRemovedKey;
  entry.bgRemovedImageUrl = incoming.bgRemovedImageUrl || entry.bgRemovedImageUrl;
  entry.bgRemovedStatus = 'completed';
  entry.bgRemoved = true;
  // Only set needsReview to true if explicitly flagged; otherwise false
  entry.needsReview = incoming.needsReview === true;
  entry.reviewReason = incoming.needsReview === true ? (incoming.reviewReason || 'transparency_fail_or_low_conf') : null;
  // Clear isFlagged if not explicitly set (completed poses should not be flagged unless QA failed)
  if (incoming.needsReview !== true) {
    entry.isFlagged = false;
  }
} else {
  entry.bgRemoved = false;
  entry.bgRemovedStatus = incoming.briaStatus;
  entry.needsReview = true;
  entry.reviewReason = incoming.reviewReason || 'unknown';
}

manifest2b.updatedAt = new Date().toISOString();

// Completion check: all approved poses are terminal
const approved2a = (manifest2a.entries || []).filter(e => e?.approved && e?.status === 'approved');
const approvedCount = approved2a.length;

const isTerminal = (s) => ['completed','failed','timeout','error'].includes(String(s||'').toLowerCase());
const approvedNums = new Set(approved2a.map(e => Number(e.poseNumber)));
const terminalApproved = (manifest2b.entries || []).filter(e => approvedNums.has(Number(e.poseNumber)) && isTerminal(e.briaStatus)).length;
const complete = (approvedCount > 0) && (terminalApproved === approvedCount);

// Order-level review flags
const approvedEntries2b = (manifest2b.entries || []).filter(e => approvedNums.has(Number(e.poseNumber)));
const needsHumanReview = approvedEntries2b.some(e => e.needsReview === true || e.needs_review === true);
const allSucceeded = approvedEntries2b.every(e => String(e.briaStatus||'').toLowerCase() === 'completed');
const readyForBook = allSucceeded && !needsHumanReview;

// Minimal summary
manifest2b.summary = manifest2b.summary || {};
manifest2b.summary.approvedPoseCount = approvedCount;
manifest2b.summary.terminalPoseCount = terminalApproved;
manifest2b.summary.complete = complete;
manifest2b.summary.needsHumanReview = needsHumanReview;
manifest2b.summary.readyForBook = readyForBook;

return [{ json: { manifest2b, complete, manifest2bKey: ctx.manifest2bKey, backendUrl: ctx.backendUrl, orderId: incoming.orderId, characterHash: incoming.characterHash } }];

/**
 * Create binary for S3 upload (manifest JSON).
 */
const manifest = $json.manifest2b;
const s = JSON.stringify(manifest, null, 2);
const b64 = Buffer.from(s, 'utf8').toString('base64');

return [{
  json: { manifest2bKey: $json.manifest2bKey, complete: $json.complete, backendUrl: $json.backendUrl, orderId: $json.orderId, characterHash: $json.characterHash, needsHumanReview: $json.manifest2b?.summary?.needsHumanReview || false },
  binary: {
    data: {
      data: b64,
      mimeType: 'application/json',
      fileName: '2b-manifest.json'
    }
  }
}];

